// Generates every token file from tokens/easm.tokens.json.
//   node tokens/build.mjs           write the generated files
//   node tokens/build.mjs --check   fail if any generated file is out of date (CI)
// Both modes also run the contrast checks in tokens/contrast.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import StyleDictionary from 'style-dictionary';
import { checkContrast } from './contrast.mjs';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = 'tokens/easm.tokens.json';
const GENERATED = 'Generated by tokens/build.mjs from tokens/easm.tokens.json. Do not edit; run `pnpm tokens`.';
const check = process.argv.includes('--check');

const camel = s => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
const num = value => typeof value === 'number' ? value : parseFloat(value);
const outputs = token => token.$extensions?.['co.easm']?.outputs;
const allows = (token, target) => !outputs(token) || outputs(token).includes(target);

// Where each source token lands. css: the --easm-ui-* name. runtime: its path in the `tokens` object.
// A token with no rule only reaches the outputs that read it explicitly (font.style and the artifact-only
// colours reach the artifact JSON); `unreached` below fails the build for any other token without a rule.
const rules = [
  [['color', '*'], p => `--easm-ui-${p[1]}`, p => ['color', camel(p[1])]],
  [['font', 'family'], () => '--easm-ui-font', () => ['typography', 'font']],
  [['font', 'size', '*'], p => `--easm-ui-text-${p[2]}`, p => ['typography', p[2]]],
  [['font', 'line-height'], () => '--easm-ui-line-height', () => ['typography', 'lineHeight']],
  [['font', 'weight', 'label'], () => '--easm-ui-weight-label', () => ['typography', 'labelWeight']],
  [['size', '*'], p => `--easm-ui-size-${p[1]}`, p => ['size', p[1]]],
  [['icon', '*'], p => p[1] === 'stroke' ? '--easm-ui-icon-stroke' : `--easm-ui-icon-size-${p[1]}`, p => ['icon', p[1]]],
  [['radius', '*'], p => `--easm-ui-radius-${p[1]}`, p => ['radius', p[1]]],
  [['space', '*'], p => `--easm-ui-space-${p[1]}`, p => ['spacing', p[1]]],
  [['motion', 'ease'], () => '--easm-ui-ease', () => ['motion', 'ease']],
  [['motion', 'ease-out'], () => '--easm-ui-ease-out', () => ['motion', 'easeOut']],
  [['motion', 'ease-in'], () => '--easm-ui-ease-in', () => ['motion', 'easeIn']],
  [['motion', 'ease-spring'], () => '--easm-ui-ease-spring', () => ['motion', 'easeSpring']],
  [['motion', 'ease-spring-soft'], () => '--easm-ui-ease-spring-soft', () => ['motion', 'easeSpringSoft']],
  [['motion', 'operation-delay'], null, () => ['motion', 'operationDelay']],
  [['motion', '*'], p => `--easm-ui-motion-${p[1]}`, p => ['motion', p[1]]],
  [['shadow', '*'], p => `--easm-ui-shadow-${p[1]}`, null],
  [['focus', 'ring'], () => '--easm-ui-focus-ring', null],
  [['focus', 'field'], () => '--easm-ui-field-focus-ring', null],
  [['focus', 'inset'], () => '--easm-ui-focus-ring-inset', null],
  [['focus', 'field-error'], () => '--easm-ui-field-error-focus-ring', null],
  [['focus', 'on-fill'], () => '--easm-ui-focus-ring-on-fill', null],
  [['z', '*'], p => `--easm-ui-z-${p[1]}`, p => ['z', p[1]]],
  [['layer', 'offset'], () => '--easm-ui-layer-offset', null],
  [['breakpoint', '*'], p => `--easm-ui-breakpoint-${p[1]}`, p => ['breakpoint', p[1]]],
];
const ruleFor = token => rules.find(([pattern]) => pattern.length === token.path.length && pattern.every((part, i) => part === '*' || part === token.path[i]));
// Tokens that deliberately have no rule: they reach the artifact JSON only.
const artifactOnly = token => (token.path[0] === 'font' && token.path[1] === 'style') || (outputs(token) && outputs(token).every(target => target === 'artifact'));

// CSS keeps references: a token whose source value names another token ({color.primary-fill}) is emitted
// as var(--easm-ui-primary-fill), so a theme or tenant that changes the referenced token changes it too.
const cssNameOf = new Map();
const reference = (ref, fallback) => cssNameOf.has(ref) ? `var(${cssNameOf.get(ref)})` : fallback;
const withReferences = (source, resolve) => source.replace(/\{([^}]+)\}/g, (whole, ref) => reference(ref, resolve(ref, whole)));
const cssValue = (token, lookup) => {
  if (token.$type === 'cubicBezier') return `cubic-bezier(${token.$value.join(', ')})`;
  const source = token.original?.$value;
  if (typeof source === 'string' && /\{[^}]+\}/.test(source)) return withReferences(source, ref => lookup(ref));
  return String(token.$value);
};
// A colour may carry a CSS expression in $extensions.co.easm.css (color-mix of another token). Browsers
// without color-mix keep the literal $value; the expression is emitted inside @supports.
const cssEnhancement = token => (token.original ?? token).$extensions?.['co.easm']?.css;

const runtimeValue = token => {
  if (token.$type === 'string') return token.$value;
  if (token.$type === 'cubicBezier') return `cubic-bezier(${token.$value.join(', ')})`;
  if (['dimension', 'duration', 'number', 'fontWeight'].includes(token.$type)) return num(token.$value);
  return token.$value;
};

// The runtime object keeps the group order of the original hand-written tokens.ts. Two groups are kept for
// compatibility and derived here: `space` (an array of the spacing values, sorted; deprecated because its
// index is not the token name) and `layer` (the z-index group under its old name).
const RUNTIME_GROUPS = ['color', 'size', 'icon', 'radius', 'space', 'spacing', 'typography', 'motion', 'layer', 'z', 'breakpoint'];
const DEPRECATED = {
  space: 'The index is not the token name: space[8] is 40 px, while space-8 is 32 px. Use tokens.spacing (keyed by token name).',
  layer: 'Use tokens.z, the name the CSS variables (--easm-ui-z-*) and the token source use.',
};
function runtimeTokens(dictionary) {
  const result = Object.fromEntries(RUNTIME_GROUPS.map(group => [group, {}]));
  for (const token of dictionary.allTokens) {
    const rule = ruleFor(token);
    if (!rule?.[2] || !allows(token, 'runtime')) continue;
    const [group, key] = rule[2](token.path);
    result[group][key] = runtimeValue(token);
  }
  result.space = Object.values(result.spacing).sort((a, b) => a - b);
  result.layer = { ...result.z };
  return result;
}
// Serialises like JSON.stringify(value, null, 2), with a @deprecated JSDoc above the deprecated groups.
function runtimeSource(runtime) {
  const entries = Object.entries(runtime).map(([group, value]) => {
    const doc = DEPRECATED[group] ? `  /** @deprecated ${DEPRECATED[group]} */\n` : '';
    return `${doc}  ${JSON.stringify(group)}: ${JSON.stringify(value, null, 2).replace(/\n/g, '\n  ')}`;
  });
  return `{\n${entries.join(',\n')}\n}`;
}

StyleDictionary.registerFormat({
  name: 'easm/css',
  format: ({ dictionary }) => {
    const byPath = new Map(dictionary.allTokens.map(token => [token.path.join('.'), token]));
    for (const token of dictionary.allTokens) {
      const css = ruleFor(token)?.[1];
      if (css && allows(token, 'css')) cssNameOf.set(token.path.join('.'), css(token.path));
    }
    const lookup = (ref, whole) => byPath.has(ref) ? String(byPath.get(ref).$value) : whole;
    const emitted = dictionary.allTokens
      .map(token => [ruleFor(token)?.[1], token])
      .filter(([css, token]) => css && allows(token, 'css'));
    const lines = emitted.map(([css, token]) => `  ${css(token.path)}: ${cssValue(token, lookup)};`);
    const enhanced = emitted.filter(([, token]) => cssEnhancement(token))
      .map(([css, token]) => `    ${css(token.path)}: ${withReferences(cssEnhancement(token), ref => lookup(ref))};`);
    const supports = enhanced.length ? `@supports (color: color-mix(in srgb, red 50%, transparent)) {\n  :root {\n${enhanced.join('\n')}\n  }\n}\n` : '';
    return `/* Namespaced product contract; existing application variables are not overwritten. */\n/* ${GENERATED} */\n:root {\n${lines.join('\n')}\n}\n${supports}`;
  },
});

// Tailwind CSS v4 theme: every EASM token as a Tailwind theme variable that points at the CSS variable,
// so utilities follow the tokens (bg-easm-surface, text-easm-text-secondary, rounded-easm-card, font-easm).
StyleDictionary.registerFormat({
  name: 'easm/tailwind',
  format: ({ dictionary }) => {
    const theme = [];
    for (const token of dictionary.allTokens) {
      const css = ruleFor(token)?.[1];
      if (!css || !allows(token, 'css')) continue;
      const name = css(token.path).replace('--easm-ui-', '');
      const [kind] = token.path;
      if (kind === 'color') theme.push(`  --color-easm-${name}: var(--easm-ui-${name});`);
      else if (kind === 'radius') theme.push(`  --radius-easm-${name.replace('radius-', '')}: var(--easm-ui-${name});`);
      else if (kind === 'font' && token.path[1] === 'size') theme.push(`  --text-easm-${name.replace('text-', '')}: var(--easm-ui-${name});`);
      else if (kind === 'font' && token.path[1] === 'family') theme.push('  --font-easm: var(--easm-ui-font);');
      else if (kind === 'motion' && token.path[1] === 'ease') theme.push('  --ease-easm: var(--easm-ui-ease);');
      else if (kind === 'motion' && token.path[1] === 'ease-out') theme.push('  --ease-easm-out: var(--easm-ui-ease-out);');
      else if (kind === 'motion' && token.path[1] === 'ease-in') theme.push('  --ease-easm-in: var(--easm-ui-ease-in);');
      // Media queries cannot read custom properties, so breakpoints carry their value (easm-medium:, easm-expanded:).
      // In rem (px / 16), the unit of Tailwind's own screens: Tailwind orders breakpoint variants by unit before
      // value, so px screens would all be emitted before sm:/md:/lg: and lose to them whenever both apply.
      else if (kind === 'breakpoint') theme.push(`  --breakpoint-easm-${token.path[1]}: ${num(token.$value) / 16}rem;`);
    }
    return `/* EASM One theme for Tailwind CSS v4. ${GENERATED} */\n/* Use after Tailwind: @import "tailwindcss"; @import "@easm-ui/ui/tailwind.css";\n   Then bg-easm-surface, bg-easm-background, text-easm-text-secondary, rounded-easm-card, font-easm, text-easm-md,\n   and the screen size classes as variants: easm-medium:, easm-expanded:, easm-large:, easm-wide:. */\n@import './tokens.css';\n\n@theme inline {\n${theme.join('\n')}\n}\n`;
  },
});

StyleDictionary.registerFormat({
  name: 'easm/ts',
  format: ({ dictionary }) => `// ${GENERATED}\n/** EASM One product tokens. Orange is a restrained brand signature. */\nexport const tokens = ${runtimeSource(runtimeTokens(dictionary))} as const;\n`,
});

StyleDictionary.registerFormat({
  name: 'easm/runtime-json',
  format: ({ dictionary }) => JSON.stringify(runtimeTokens(dictionary), null, 2) + '\n',
});

// The Claude Design System artifact's token file: names in kebab case, with usage notes.
StyleDictionary.registerFormat({
  name: 'easm/artifact-json',
  format: ({ dictionary }) => {
    const group = (...prefix) => dictionary.allTokens.filter(t => prefix.every((p, i) => t.path[i] === p) && allows(t, 'artifact'));
    const withUsage = (tokens, name) => tokens.filter(t => t.$description).map(t => ({ name: name(t), value: String(t.$value), usage: t.$description }));
    const source = JSON.parse(fs.readFileSync(path.join(repo, SOURCE), 'utf8'));
    const artifact = {
      name: 'EASM One',
      version: 1,
      meta: {
        source: 'local',
        paths: { tokens: [SOURCE], assets: ['brand-assets/design-system/assets/brand'] },
        synced: source.$extensions['co.easm'].artifactSynced,
      },
      color: {
        themes: [{ id: 'light', name: 'Light' }],
        tokens: group('color').map(t => ({ name: t.path[1], value: { light: t.$value.toLowerCase() }, usage: t.$description })),
      },
      type: {
        fonts: [],
        families: { sans: dictionary.tokens.font.family.$value.replaceAll("'", '"') },
        groups: [{
          name: 'Text',
          family: 'sans',
          styles: group('font', 'style').map(t => ({ name: t.path[2], fontSize: t.$value.fontSize, lineHeight: num(t.$value.lineHeight), fontWeight: num(t.$value.fontWeight), usage: t.$description })),
        }],
      },
      spacing: { tokens: withUsage(group('space'), t => `space-${t.path[1]}`) },
      radius: { tokens: withUsage(group('radius'), t => `radius-${t.path[1]}`) },
      shadow: { tokens: withUsage(group('shadow'), t => `shadow-${t.path[1]}`) },
    };
    return JSON.stringify(artifact, null, 2) + '\n';
  },
});

const sd = new StyleDictionary({
  source: [path.join(repo, SOURCE)],
  // Style Dictionary's own warnings stay off: with no name transform every `sm`/`md` token "collides", which is
  // expected because the formats above name tokens by path. The `unreached` check below covers silent loss.
  log: { verbosity: 'silent', warnings: 'disabled' },
  platforms: {
    easm: {
      transforms: [],
      files: [
        { destination: 'packages/ui/src/tokens.css', format: 'easm/css' },
        { destination: 'packages/ui/src/tokens.generated.ts', format: 'easm/ts' },
        { destination: 'packages/ui/src/tailwind.css', format: 'easm/tailwind' },
        { destination: 'brand-assets/components/library/tokens.json', format: 'easm/runtime-json' },
        { destination: 'claude-design-system/project/tokens.json', format: 'easm/artifact-json' },
      ],
    },
  },
});

const files = await sd.formatPlatform('easm');
const stale = [];
const write = (destination, output) => {
  const file = path.join(repo, destination);
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === output) return;
  if (check) stale.push(destination);
  else { fs.writeFileSync(file, output); console.log(`wrote ${destination}`); }
};
// The design workshop (a separate repository) also keeps copies for its catalogue and artifact; they are
// written only where that folder exists, so this repository builds on its own.
const optional = destination => /^(brand-assets|claude-design-system)\//.test(destination);
for (const { output, destination } of files) {
  if (optional(destination) && !fs.existsSync(path.dirname(path.join(repo, destination)))) continue;
  write(destination, output);
}

const dictionary = await sd.getPlatformTokens('easm');
const flatten = node => node && typeof node === 'object' ? ('$value' in node ? [node] : Object.values(node).flatMap(flatten)) : [];
const allTokens = dictionary.allTokens ?? flatten(dictionary.tokens);

// Every token must reach an output: a new group with no rule would otherwise vanish silently.
const unreached = allTokens.filter(token => !ruleFor(token) && !artifactOnly(token)).map(token => token.path.join('.'));

// The token tables in the foundation doc are generated from the same source, between marker comments.
const FOUNDATIONS = 'packages/ui/docs/FOUNDATIONS.md';
const docErrors = [];
const byPath = new Map(allTokens.map(token => [token.path.join('.'), token]));
const docValue = token => {
  const source = token.original?.$value;
  const ref = typeof source === 'string' && /^\{[^}]+\}$/.test(source) ? source.slice(1, -1) : null;
  return ref ? `${token.$value} (= ${ref.replace(/^color\./, '')})` : String(token.$value);
};
const cell = text => String(text ?? '').replace(/\|/g, '\\|');
const group = (...prefix) => allTokens.filter(token => prefix.every((part, i) => token.path[i] === part));
const list = (tokens, unit = '') => tokens.map(token => `${token.path.at(-1)}: ${String(token.$value).replace(/px$|ms$/, '')}`).join(', ') + unit;
const generated = {
  colors: [
    '| Variable | Value | Use |',
    '| --- | --- | --- |',
    ...group('color').filter(token => allows(token, 'css')).map(token => `| \`--easm-ui-${token.path[1]}\` | ${cell(docValue(token))} | ${cell(token.$description)} |`),
  ].join('\n'),
  scales: [
    `- Type: font \`${byPath.get('font.family').$value}\`; sizes (\`--easm-ui-text-*\`) ${list(group('font', 'size'), ' px')}; line height ${byPath.get('font.line-height').$value}; label weight ${byPath.get('font.weight.label').$value}.`,
    `- Spacing (\`--easm-ui-space-*\`, \`tokens.spacing\`): ${list(group('space'), ' px')}.`,
    `- Control heights (\`--easm-ui-size-*\`): ${list(group('size'), ' px')}. Icons (\`--easm-ui-icon-size-*\`): ${list(group('icon').filter(token => token.path[1] !== 'stroke'), ' px')}; stroke ${byPath.get('icon.stroke').$value}.`,
    `- Radius (\`--easm-ui-radius-*\`): ${list(group('radius'), ' px')}.`,
    `- Motion (\`--easm-ui-motion-*\`): ${list(group('motion').filter(token => token.$type === 'duration' && token.path[1] !== 'operation-delay'), ' ms')}; easing \`${cssValue(byPath.get('motion.ease'), () => '')}\`.`,
    `- Focus: ring \`${byPath.get('focus.ring').original.$value}\`; field \`${byPath.get('focus.field').original.$value}\`; inset \`${byPath.get('focus.inset').original.$value}\`; field in error \`${byPath.get('focus.field-error').original.$value}\`.`,
    `- Layers (\`--easm-ui-z-*\`, \`tokens.z\`): ${list(group('z'))}. Screen size classes (\`tokens.breakpoint\`, Tailwind \`easm-*:\`): ${list(group('breakpoint'), ' px')} (compact below medium; the Tailwind variants carry the same values in rem, px / 16, so they sort with sm:, md: and lg:).`,
  ].join('\n'),
};
if (fs.existsSync(path.join(repo, FOUNDATIONS))) {
  let doc = fs.readFileSync(path.join(repo, FOUNDATIONS), 'utf8');
  for (const [name, body] of Object.entries(generated)) {
    const pattern = new RegExp(`(<!-- generated:${name} [^>]*-->)[\\s\\S]*?(<!-- /generated:${name} -->)`);
    if (!pattern.test(doc)) { docErrors.push(`${FOUNDATIONS}: missing <!-- generated:${name} --> markers`); continue; }
    doc = doc.replace(pattern, (whole, open, close) => `${open}\n${body}\n${close}`);
  }
  write(FOUNDATIONS, doc);
}

const { failures, warnings } = checkContrast(dictionary.tokens);

if (warnings.length) console.warn(`Contrast warnings:\n  ${warnings.join('\n  ')}`);
if (stale.length) console.error(`Out of date (run \`pnpm tokens\`):\n  ${stale.join('\n  ')}`);
if (unreached.length) console.error(`Tokens that reach no output (add a rule in tokens/build.mjs):\n  ${unreached.join('\n  ')}`);
if (docErrors.length) console.error(docErrors.join('\n'));
if (failures.length) console.error(`Contrast failures:\n  ${failures.join('\n  ')}`);
if (stale.length || failures.length || unreached.length || docErrors.length) process.exit(1);
console.log(check ? 'Tokens: generated files are current; contrast checks pass.' : 'Tokens: built; contrast checks pass.');
